<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, action } from '../api'
const path=ref(''); const kind=ref('brief'),query=ref(''),title=ref(''),content=ref(''),source=ref(''),module=ref('personal'),sourcePath=ref(''),destination=ref('技术/归档'),sources=ref<any[]>([]),sourceId=ref(''),result=ref<any>(null),pending=ref<any>(null),busy=ref(false)
async function load(){sources.value=(await api('/wiki-sources')).items}
async function run(confirm=false){busy.value=true;await action(async()=>{let p:any,tool:string;if(confirm){p={...pending.value.parameters,confirm:true};tool=pending.value.tool}else{tool=['promote','archive'].includes(kind.value)?'assistant_memory':kind.value==='validate'?'assistant_admin':'assistant_knowledge';p={action:kind.value};if(['brief','search'].includes(kind.value))p.query=query.value;if(kind.value==='read')p.path=path.value;if(kind.value==='promote')Object.assign(p,{title:title.value,content:content.value,source:source.value,module:module.value});if(kind.value==='archive')Object.assign(p,{source_path:sourcePath.value,destination:destination.value});pending.value=['promote','archive'].includes(kind.value)?{tool,parameters:p}:null}result.value=await api('/governance/'+tool,'POST',{parameters:p});if(confirm)pending.value=null},confirm?'已保存至受管 Wiki':'处理完成');busy.value=false}
async function importWiki(confirm=false){busy.value=true;await action(async()=>{result.value=await api('/governance/import','POST',{source_id:confirm?pending.value.source_id:sourceId.value,confirm});pending.value=confirm?null:{import:true,source_id:sourceId.value}},confirm?'Wiki 已迁入，原目录保持不变':'导入预览已生成');busy.value=false}
onMounted(()=>action(load,''))
</script>
<template><div class="page-title"><div><h1>知识治理</h1><p>统一读取、任务简报、知识晋升和资料归档；新内容保存在服务数据目录。</p></div></div><section class="form-panel"><h2>迁入旧 Wiki</h2><p class="muted">完整复制已有 Wiki 的文档与目录结构，原文件不修改。迁入后可在这里持续维护；目录增量检索仍由“Wiki 目录”管理。</p><label>已接入目录<select v-model="sourceId"><option value="">请选择来源</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button :disabled="!sourceId||busy" @click="importWiki()">预览迁入</button></section><form class="form-panel" @submit.prevent="run()"><label>操作<select v-model="kind" @change="pending=null;result=null"><option value="brief">任务简报</option><option value="search">全文检索</option><option value="read">读取文档</option><option value="promote">晋升长期知识</option><option value="archive">归档资料</option><option value="analyze">结构分析</option><option value="initialize">增量索引</option><option value="validate">治理校验</option></select></label><label v-if="['brief','search'].includes(kind)">查询或任务描述<input v-model="query" required></label><label v-if="kind==='read'">Wiki 相对路径<input v-model="path" required></label><template v-if="kind==='promote'"><label>标题<input v-model="title" required></label><label>知识正文<textarea v-model="content" required rows="8"></textarea></label><label>来源引用<input v-model="source" required placeholder="任务、来源文档或验证记录"></label><label>模块短码<input v-model="module" required></label></template><template v-if="kind==='archive'"><label>源文档路径<input v-model="sourcePath" required placeholder="已登记项目或 Wiki 中的容器路径"></label><label>目标相对目录<input v-model="destination" required></label></template><button class="primary" :disabled="busy">{{busy?'正在处理…':['promote','archive'].includes(kind)?'生成写入预览':'执行'}}</button></form><section v-if="result" class="form-panel"><h2>处理结果</h2><pre class="result-text">{{JSON.stringify(result,null,2)}}</pre><button v-if="pending" class="primary" :disabled="busy" @click="pending.import?importWiki(true):run(true)">确认{{pending.import?'迁入':'写入'}}</button></section></template>
